{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2137-08-30 21:45:00",
      "speaker": "Doctor",
      "text": "Hello Mr. ___, I'm Dr. ___, one of your hospital doctors. You're here tonight for your scheduled bronchoscopy with balloon dilation. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2137-08-30 21:46:30",
      "speaker": "Patient",
      "text": "Hi doctor. I’m okay, a bit nervous. My breathing’s been a little worse since last time, but not bad right now."
    },
    {
      "turn_number": 3,
      "time": "2137-08-30 21:48:00",
      "speaker": "Doctor",
      "text": "That makes sense. Your CT scan showed the trachea and bronchi are still narrowed from your polychondritis. The procedure tomorrow will help open them up again."
    },
    {
      "turn_number": 4,
      "time": "2137-08-30 21:49:20",
      "speaker": "Patient",
      "text": "Right, like last time. I remember the dilation helped. But I’ve been seeing those lung spots on my scans—should I worry?"
    },
    {
      "turn_number": 5,
      "time": "2137-08-30 21:51:00",
      "speaker": "Doctor",
      "text": "The new spots on your left lower lobe and right lung apex could be infection or inflammation. But you’re not running a fever or coughing more, so we don’t think it’s active. Infectious disease agrees—no antibiotics for now."
    },
    {
      "turn_number": 6,
      "time": "2137-08-30 21:52:30",
      "speaker": "Patient",
      "text": "Okay, that’s a relief. But my white count is high again, right? It was 19.6 when I came in."
    },
    {
      "turn_number": 7,
      "time": "2137-08-30 21:54:00",
      "speaker": "Doctor",
      "text": "Yes, your white count is elevated, mostly neutrophils. But since you’re not sick-appearing and cultures show colonizing bacteria like Pseudomonas and Klebsiella, we believe this is from chronic airway inflammation, not a new infection."
    },
    {
      "turn_number": 8,
      "time": "2137-08-30 21:55:30",
      "speaker": "Patient",
      "text": "So the bacteria in my lungs are just… living there?"
    },
    {
      "turn_number": 9,
      "time": "2137-08-30 21:56:45",
      "speaker": "Doctor",
      "text": "Exactly. They’re colonizers—common in patients with tracheostomies and chronic airway disease. Treating them wouldn’t help and might cause resistance."
    },
    {
      "turn_number": 10,
      "time": "2137-08-30 21:58:00",
      "speaker": "Patient",
      "text": "Got it. What about after the procedure? Will I be in pain?"
    },
    {
      "turn_number": 11,
      "time": "2137-08-30 21:59:15",
      "speaker": "Doctor",
      "text": "You might have some soreness around the trach site. We’ll give oxycodone and acetaminophen as needed. Most patients say it feels like usual post-dilation discomfort."
    },
    {
      "turn_number": 12,
      "time": "2137-08-31 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. The bronchoscopy went well—no complications. They dilated your trachea and main bronchi. You had some mucosal inflammation, but that’s expected."
    },
    {
      "turn_number": 13,
      "time": "2137-08-31 08:31:30",
      "speaker": "Patient",
      "text": "That’s good. My breathing feels about the same so far."
    },
    {
      "turn_number": 14,
      "time": "2137-08-31 08:33:00",
      "speaker": "Doctor",
      "text": "It might take a day or two to notice improvement. We’ve started you on 50 mg of prednisone to reduce airway swelling, and you’ll taper it down over the next few weeks."
    },
    {
      "turn_number": 15,
      "time": "2137-08-31 08:34:30",
      "speaker": "Patient",
      "text": "I was only on 2.5 mg before. Is such a high dose safe?"
    },
    {
      "turn_number": 16,
      "time": "2137-08-31 08:36:00",
      "speaker": "Doctor",
      "text": "It’s a short course. We’re using it to calm the inflammation after the procedure. You’ll decrease by 10 mg every three days until you’re back to 7.5 mg."
    },
    {
      "turn_number": 17,
      "time": "2137-08-31 14:00:00",
      "speaker": "Doctor",
      "text": "Your labs are improving—white count dropped to 13.3. You’re saturating well on 40% oxygen. We’re comfortable sending you home today."
    },
    {
      "turn_number": 18,
      "time": "2137-08-31 14:02:00",
      "speaker": "Patient",
      "text": "Great. What should I watch for at home?"
    },
    {
      "turn_number": 19,
      "time": "2137-08-31 14:03:30",
      "speaker": "Doctor",
      "text": "Keep an eye on your breathing, fever, or increased secretions. Finish the prednisone taper, stay on your regular methotrexate and inhalers."
    },
    {
      "turn_number": 20,
      "time": "2137-08-31 14:05:00",
      "speaker": "Patient",
      "text": "And my follow-up?"
    },
    {
      "turn_number": 21,
      "time": "2137-08-31 14:06:15",
      "speaker": "Doctor",
      "text": "You’ll see interventional pulmonology and rheumatology soon. We’ll also repeat a CBC to monitor your white count."
    },
    {
      "turn_number": 22,
      "time": "2137-08-31 17:00:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. Your breathing sounds stable, and your trach site looks good—just a little redness, no infection."
    },
    {
      "turn_number": 23,
      "time": "2137-08-31 17:01:30",
      "speaker": "Patient",
      "text": "I feel ready to go home. Thanks for explaining everything."
    },
    {
      "turn_number": 24,
      "time": "2137-08-31 17:03:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: take the prednisone as directed, use albuterol if short of breath, and call if anything changes."
    },
    {
      "turn_number": 25,
      "time": "2137-08-31 17:04:30",
      "speaker": "Patient",
      "text": "I will. And I have my appointments lined up."
    },
    {
      "turn_number": 26,
      "time": "2137-08-31 17:06:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll see you in follow-up. Take care, Mr. ___."
    },
    {
      "turn_number": 27,
      "time": "2137-08-31 17:07:30",
      "speaker": "Patient",
      "text": "Thank you, doctor. Have a good day."
    },
    {
      "turn_number": 28,
      "time": "2137-08-31 17:09:00",
      "speaker": "Doctor",
      "text": "You too. The team will get your discharge papers ready."
    }
  ],
  "summary": {
    "admission_start": "2137-08-30 21:37:00",
    "admission_end": "2137-08-31 19:18:00",
    "summary_paragraph": "Mr. ___ was admitted for a scheduled bronchoscopy with balloon dilation due to recurrent tracheobronchial stenosis from relapsing polychondritis and Ruvalcaba-Myhre-Smith syndrome. The procedure was performed without complications, and he was observed post-operatively. His breathing remained stable, and pain was controlled with oxycodone. Elevated white blood cell count persisted but was attributed to chronic inflammation rather than active infection, supported by the absence of fever or increased secretions. He was started on a prednisone taper from 50 mg to his baseline 7.5 mg and discharged home in stable condition with follow-up planned in pulmonology and rheumatology.",
    "problems": [
      "Other specified diseases of upper respiratory tract",
      "Other diseases of bronchus, not elsewhere classified",
      "Ruvalcaba-Myhre-Smith syndrome",
      "Relapsing polychondritis",
      "Tracheostomy status",
      "Gastro-esophageal reflux disease without esophagitis",
      "Atrophy of testis",
      "Elevated white blood cell count, unspecified"
    ]
  }
}
